const listWorkOrders = `-- name: ListWorkOrders :many
SELECT wo.id, wo.company_id, wo.number, wo.title, wo.description, wo.asset_id, wo.location_id,
       wo.priority, wo.status, wo.category, wo.requester_id, wo.assignee_id,
       wo.planned_start, wo.planned_end, wo.actual_start, wo.actual_end,
       wo.estimated_hours, wo.actual_hours, wo.created_by, wo.created_at, wo.updated_at,
       a.name AS asset_name, l.name AS location_name
FROM work_orders wo
LEFT JOIN assets a ON wo.asset_id = a.id
LEFT JOIN locations l ON wo.location_id = l.id
WHERE wo.company_id = $1
  AND ($2::int8 IS NULL OR wo.asset_id = $2)
  AND ($3::int8 IS NULL OR wo.location_id = $3)
  AND ($4::int8 IS NULL OR wo.assignee_id = $4)
  AND ($5::text IS NULL OR wo.status = $5)
  AND ($6::text IS NULL OR wo.priority = $6)
  AND ($7::text IS NULL OR wo.category = $7)
  AND ($8::timestamptz IS NULL OR wo.planned_start >= $8)
  AND ($9::timestamptz IS NULL OR wo.planned_end <= $9)
ORDER BY wo.planned_start ASC NULLS LAST
LIMIT $10 OFFSET $11
`

type ListWorkOrdersParams struct {
	CompanyID int64              `json:"company_id"`
	Column2   int64              `json:"column_2"`
	Column3   int64              `json:"column_3"`
	Column4   int64              `json:"column_4"`
	Column5   string             `json:"column_5"`
	Column6   string             `json:"column_6"`
	Column7   string             `json:"column_7"`
	Column8   pgtype.Timestamptz `json:"column_8"`
	Column9   pgtype.Timestamptz `json:"column_9"`
	Limit     int32              `json:"limit"`
	Offset    int32              `json:"offset"`
}

type ListWorkOrdersRow struct {
	ID             int64              `json:"id"`
	CompanyID      int64              `json:"company_id"`
	Number         string             `json:"number"`
	Title          string             `json:"title"`
	Description    pgtype.Text        `json:"description"`
	AssetID        pgtype.Int8        `json:"asset_id"`
	LocationID     pgtype.Int8        `json:"location_id"`
	Priority       string             `json:"priority"`
	Status         string             `json:"status"`
	Category       string             `json:"category"`
	RequesterID    int64              `json:"requester_id"`
	AssigneeID     pgtype.Int8        `json:"assignee_id"`
	PlannedStart   pgtype.Timestamptz `json:"planned_start"`
	PlannedEnd     pgtype.Timestamptz `json:"planned_end"`
	ActualStart    pgtype.Timestamptz `json:"actual_start"`
	ActualEnd      pgtype.Timestamptz `json:"actual_end"`
	EstimatedHours float64            `json:"estimated_hours"`
	ActualHours    float64            `json:"actual_hours"`
	CreatedBy      int64              `json:"created_by"`
	CreatedAt      pgtype.Timestamptz `json:"created_at"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	AssetName      pgtype.Text        `json:"asset_name"`
	LocationName   pgtype.Text        `json:"location_name"`
}

func (q *Queries) ListWorkOrders(ctx context.Context, arg ListWorkOrdersParams) ([]ListWorkOrdersRow, error) {
	rows, err := q.db.Query(ctx, listWorkOrders,
		arg.CompanyID,
		arg.Column2,
		arg.Column3,
		arg.Column4,
		arg.Column5,
		arg.Column6,
		arg.Column7,
		arg.Column8,
		arg.Column9,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWorkOrdersRow
	for rows.Next() {
		var i ListWorkOrdersRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Number,
			&i.Title,
			&i.Description,
			&i.AssetID,
			&i.LocationID,
			&i.Priority,
			&i.Status,
			&i.Category,
			&i.RequesterID,
			&i.AssigneeID,
			&i.PlannedStart,
			&i.PlannedEnd,
			&i.ActualStart,
			&i.ActualEnd,
			&i.EstimatedHours,
			&i.ActualHours,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.AssetName,
			&i.LocationName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

